def solve(coins, amount):
    # Minimum number of coins (unlimited supply) to make `amount`, or -1.
    if amount == 0:
        return 0
    if amount < 0 or not coins:
        return -1
    INF = float('inf')
    dp = [0] + [INF] * amount
    for i in range(1, amount + 1):
        for c in coins:
            if 0 < c <= i and dp[i - c] + 1 < dp[i]:
                dp[i] = dp[i - c] + 1
    return dp[amount] if dp[amount] < INF else -1

