def solve(s):
    # Longest palindromic substring; ties -> the one that starts first.
    if not s:
        return ''
    best_start, best_len = 0, 1

    def expand(l, r):
        while l >= 0 and r < len(s) and s[l] == s[r]:
            l -= 1
            r += 1
        return l + 1, r - l - 1  # start, length

    for center in range(len(s)):
        # Odd-length palindromes centered at `center`.
        st, ln = expand(center, center)
        if ln > best_len:
            best_start, best_len = st, ln
        # Even-length palindromes centered between center and center+1.
        st, ln = expand(center, center + 1)
        if ln > best_len:
            best_start, best_len = st, ln
    return s[best_start:best_start + best_len]

