def solve(matrix):
    """Return the determinant of an integer square matrix.
    Uses the Bareiss fraction‑free algorithm (O(n³)) which stays in integer arithmetic.
    An empty matrix has determinant 1.
    """
    # Empty matrix case
    if not matrix:
        return 1
    n = len(matrix)
    # Verify square matrix
    for row in matrix:
        if len(row) != n:
            raise ValueError("Matrix must be square")
    # Make a copy to avoid mutating input
    a = [list(map(int, row)) for row in matrix]
    if n == 1:
        return a[0][0]
    sign = 1  # track row swaps affecting sign
    prev = 1  # denominator from previous elimination step
    for k in range(n - 1):
        # Pivot selection: if zero, swap with a lower row that has non‑zero in same column
        if a[k][k] == 0:
            swap_row = None
            for i in range(k + 1, n):
                if a[i][k] != 0:
                    swap_row = i
                    break
            if swap_row is None:
                return 0  # singular matrix
            a[k], a[swap_row] = a[swap_row], a[k]
            sign = -sign
        pivot = a[k][k]
        if pivot == 0:
            return 0
        # Bareiss elimination step – keep everything integral
        for i in range(k + 1, n):
            for j in range(k + 1, n):
                # The division is exact by the properties of the algorithm
                a[i][j] = (a[i][j] * pivot - a[i][k] * a[k][j]) // prev
            a[i][k] = 0
        prev = pivot
    # After the last iteration the determinant is the final diagonal entry times the sign
    return sign * a[n - 1][n - 1]

