def solve(s):
    # Longest palindromic substring; ties -> earliest start.
    # Two-pass Manacher (odd and even centers) on the raw string: fast, O(n).
    n = len(s)
    if n < 2:
        return s
    # Odd-length palindromes centered at i.
    d1 = [0] * n
    l, r = 0, -1
    bestL, bestS = 0, 0
    for i in range(n):
        if i > r:
            k = 1
        else:
            k = d1[l + r - i]
            m = r - i + 1
            if k > m:
                k = m
        while i - k >= 0 and i + k < n and s[i - k] == s[i + k]:
            k += 1
        d1[i] = k
        L = 2 * k - 1
        if L > bestL:
            bestL, bestS = L, i - k + 1
        k -= 1
        if i + k > r:
            l, r = i - k, i + k
        if bestL == n:
            return s
    # Even-length palindromes centered between i-1 and i.
    d2 = [0] * n
    l, r = 0, 0
    for i in range(n):
        if i > r:
            k = 0
        else:
            k = d2[l + r - i + 1]
            m = r - i + 1
            if k > m:
                k = m
        while i - k - 1 >= 0 and i + k < n and s[i - k - 1] == s[i + k]:
            k += 1
        d2[i] = k
        L = 2 * k
        if L > bestL:
            bestL, bestS = L, i - k
        k -= 1
        if i + k > r:
            l, r = i - k - 1, i + k
    return s[bestS:bestS + bestL]

