def solve(grid):
    """Count islands in a possibly jagged grid.
    grid is a list of lists containing 0/1 values. Cells are 4-directionally connected.
    """
    if not grid:
        return 0
    n = len(grid)
    visited = [ [False]*len(row) for row in grid ]
    def dfs(i, j):
        stack = [(i, j)]
        while stack:
            x, y = stack.pop()
            if visited[x][y]:
                continue
            visited[x][y] = True
            # explore 4 neighbors
            # up
            if x-1 >= 0 and y < len(grid[x-1]) and not visited[x-1][y] and grid[x-1][y] == 1:
                stack.append((x-1, y))
            # down
            if x+1 < n and y < len(grid[x+1]) and not visited[x+1][y] and grid[x+1][y] == 1:
                stack.append((x+1, y))
            # left
            if y-1 >= 0 and not visited[x][y-1] and grid[x][y-1] == 1:
                stack.append((x, y-1))
            # right
            if y+1 < len(grid[x]) and not visited[x][y+1] and grid[x][y+1] == 1:
                stack.append((x, y+1))
    count = 0
    for i, row in enumerate(grid):
        for j, val in enumerate(row):
            if val == 1 and not visited[i][j]:
                dfs(i, j)
                count += 1
    return count

