def solve(matrix):
    # Bareiss algorithm for exact integer determinant
    n = len(matrix)
    if n == 0:
        return 1
    # make a copy to avoid mutating input
    A = [row[:] for row in matrix]
    det = 1
    for k in range(n-1):
        # Find pivot if zero
        if A[k][k] == 0:
            # search for non-zero pivot in rows below
            for i in range(k+1, n):
                if A[i][k] != 0:
                    A[k], A[i] = A[i], A[k]
                    det = -det
                    break
            else:
                return 0
        pivot = A[k][k]
        for i in range(k+1, n):
            for j in range(k+1, n):
                # Compute using integer arithmetic
                A[i][j] = (A[i][j]*pivot - A[i][k]*A[k][j]) // (A[k-1][k-1] if k>0 else 1)
        # Zero out column below pivot
        for i in range(k+1, n):
            A[i][k] = 0
    det *= A[n-1][n-1]
    return det

