def solve(matrix):
    # Using recursive Laplace expansion for small matrices for correctness verification
    def det(mat):
        n = len(mat)
        if n==0:
            return 1
        if n==1:
            return mat[0][0]
        if n==2:
            return mat[0][0]*mat[1][1] - mat[0][1]*mat[1][0]
        total=0
