    n = len(matrix)
    if n == 0:
        return 1
    # Make a deep copy to avoid mutating the input
    A = [row[:] for row in matrix]
    sign = 1
    for k in range(n - 1):
        # Pivot handling: if pivot is zero, swap with a lower row
        if A[k][k] == 0:
            for i in range(k + 1, n):
                if A[i][k] != 0:
                    A[k], A[i] = A[i], A[k]
                    sign = -sign
                    break
            else:
                return 0
        pivot = A[k][k]
        prev_pivot = A[k - 1][k - 1] if k > 0 else 1
        for i in range(k + 1, n):
            for j in range(k + 1, n):
                # Bareiss update ensures integer division without remainder
                A[i][j] = (A[i][j] * pivot - A[i][k] * A[k][j]) // prev_pivot
