def solve(n, b):
    # Convert integer n to base b (2..36), digits 0-9 then a-z,
    # leading '-' for negative n.
    if n == 0:
        return '0'
    digits = '0123456789abcdefghijklmnopqrstuvwxyz'
    sign = ''
    if n < 0:
        sign = '-'
        n = -n
    out = []
    while n:
        n, r = divmod(n, b)
        out.append(digits[r])
    return sign + ''.join(reversed(out))

