def solve(s):
    """Return length of the longest substring without repeating characters.
    Uses sliding window with a dictionary storing the last index of each character.
    Runs in O(n) time and O(min(n, alphabet)) space.
    """
    if not isinstance(s, str):
        # Non-string input is treated as empty string per spec simplification
        return 0
    last_idx = {}
    max_len = 0
    start = 0  # start index of current window
    for i, ch in enumerate(s):
        if ch in last_idx and last_idx[ch] >= start:
            # repeated character inside current window; move start
            start = last_idx[ch] + 1
        last_idx[ch] = i
        cur_len = i - start + 1
        if cur_len > max_len:
            max_len = cur_len
    return max_len

