def solve(arr):
    """Return length of longest strictly increasing subsequence.
    Handles empty input and non‑list iterables gracefully.
    """
    # Guard against non‑iterable or None
    if arr is None:
        return 0
    try:
        seq = list(arr)
    except Exception:
        return 0
    if not seq:
        return 0
    import bisect
    tails = []  # tails[i] = smallest possible tail of an IS of length i+1
    for x in seq:
        # Find insertion point in tails
        idx = bisect.bisect_left(tails, x)
        if idx == len(tails):
            tails.append(x)
        else:
            tails[idx] = x
    return len(tails)

