import heapq

def solve(n, edges):
    # Shortest path from node 0 to node n-1 in an undirected graph
    # with positive weights ([a, b, w] edges); -1 if unreachable.
    if n <= 0:
        return -1
    if n == 1:
        return 0
    adj = [[] for _ in range(n)]
    for e in edges:
        a, b, w = e[0], e[1], e[2]
        adj[a].append((b, w))
        adj[b].append((a, w))
    INF = float('inf')
    dist = [INF] * n
    dist[0] = 0
    heap = [(0, 0)]
    while heap:
        d, u = heapq.heappop(heap)
        if d > dist[u]:
            continue
        if u == n - 1:
            return d
        for v, w in adj[u]:
            nd = d + w
            if nd < dist[v]:
                dist[v] = nd
                heapq.heappush(heap, (nd, v))
    return dist[n - 1] if dist[n - 1] < INF else -1

